protected Class<?> loadClass(String name, boolean resolve) {
    synchronized (getClassLoadingLock(name)) {
        Class<?> c = findLoadedClass(name);   // 1 已加载?
        if (c == null) {
            try {
                if (parent != null) c = parent.loadClass(name, false); // 2 委派父
                else c = findBootstrapClassOrNull(name);
            } catch (ClassNotFoundException ignored) { }
            if (c == null) c = findClass(name);  // 3 自己加载
        }
        if (resolve) resolveClass(c);
        return c;
    }
}

// 方式一：重写 loadClass，先自己加载
@Override
protected Class<?> loadClass(String name, boolean resolve) {
    Class<?> c = findLoadedClass(name);
    if (c == null) {
        try { c = findClass(name); }
        catch (ClassNotFoundException e) { c = super.loadClass(name, resolve); }
    }
    return c;
}

