@Benchmark
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 5, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(2)
public class MyBenchmark {
    @Benchmark
    public int test(Blackhole bh) {
        int sum = 0;
        for (int i = 0; i < 100; i++) sum += i;
        bh.consume(sum);
        return sum;
    }
}

