@Around("@annotation(com.example.Retry)")
public Object retry(ProceedingJoinPoint pjp) throws Throwable {
    int attempts = 0;
    while (true) {
        try {
            return pjp.proceed();
        } catch (Exception e) {
            if (++attempts >= 3) throw e;
        }
    }
}

